{
  "findings": [
    {
      "check_id": "CKV_AZURE_35",
      "title": "Storage account permits network access by default",
      "resource": "azurerm_storage_account_network_rules.notification_storage_rules",
      "severity": "MEDIUM",
      "explanation": "The default_action is set to \"Allow\", making the storage account reachable from networks not explicitly listed in ip_rules. Default-deny access limits exposure to approved network exceptions and configured bypass services."
    }
  ],
  "patched_code": "resource \"azurerm_storage_account_network_rules\" \"notification_storage_rules\" {\n  storage_account_id = azurerm_storage_account.notification_storage.id\n  default_action     = \"Deny\"\n  ip_rules           = [\"127.0.0.1\"]\n  bypass             = [\"Metrics\", \"Logging\"]\n}\n",
  "fix_summary": "Changed the storage account network rules from default allow to default deny, restricting access to explicitly configured exceptions."
}
